<?php require_once __DIR__.'/../includes/functions.php';require_role('student');$pageTitle='Dashboard';$base='../';require __DIR__.'/../includes/header.php';?>
<div class="layout"><?php require __DIR__.'/../includes/sidebar.php';?><section class="content"><div class="card"><h1>Welcome, <?=e($_SESSION['user']['name'])?></h1><p class="muted">Student dashboard</p></div><div class="grid" style="margin-top:18px"><div class='card'><div class='muted'>Present Days</div><div class='stat'><?=e(metric($pdo,"SELECT COUNT(*) FROM attendance a JOIN students s ON s.id=a.student_id WHERE s.user_id=? AND a.status='Present'",[$_SESSION['user']['id']]))?></div></div><div class='card'><div class='muted'>Assignments</div><div class='stat'><?=e(metric($pdo,"SELECT COUNT(*) FROM assignments a JOIN students s ON s.class_id=a.class_id WHERE s.user_id=?",[$_SESSION['user']['id']]))?></div></div><div class='card'><div class='muted'>Upcoming Exams</div><div class='stat'><?=e(metric($pdo,"SELECT COUNT(*) FROM exams e JOIN students s ON s.class_id=e.class_id WHERE s.user_id=? AND e.exam_date>=CURDATE()",[$_SESSION['user']['id']]))?></div></div><div class='card'><div class='muted'>Unread Notifications</div><div class='stat'><?=e(metric($pdo,"SELECT COUNT(*) FROM notifications WHERE user_id=? AND is_read=0",[$_SESSION['user']['id']]))?></div></div></div></section></div><?php require __DIR__.'/../includes/footer.php';?>